'use client';

import { cn } from '@/lib/utils';
import './style.css';

/*
 * @author: @joao-carmassi
 * @description: Animated shining radial-gradient border effect.
 * Drop <ShineBorder /> inside any Card (with `relative` on the Card).
 * @version: 1.0.0
 * @date: 2026-24-03
 * @license: MIT
 * @reference: https://magicui.design/docs/components/shine-border
 */

interface ShineBorderProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Width of the border in pixels
   * @default 1
   */
  borderWidth?: number;
  /**
   * Duration of the animation in seconds
   * @default 14
   */
  duration?: number;
  /**
   * Color of the border, can be a single color or an array of colors
   * @default "#000000"
   */
  shineColor?: string | string[];
}

/**
 * Shine Border
 *
 * An animated background border effect component with configurable properties.
 */
export function ShineBorder({
  borderWidth = 1,
  duration = 14,
  shineColor = '#000000',
  className,
  style,
  ...props
}: ShineBorderProps) {
  return (
    <div
      style={
        {
          '--border-width': `${borderWidth}px`,
          '--duration': `${duration}s`,
          backgroundImage: `radial-gradient(transparent,transparent, ${
            Array.isArray(shineColor) ? shineColor.join(',') : shineColor
          },transparent,transparent)`,
          backgroundSize: '300% 300%',
          mask: `linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)`,
          WebkitMask: `linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)`,
          WebkitMaskComposite: 'xor',
          maskComposite: 'exclude',
          padding: 'var(--border-width)',
          ...style,
        } as React.CSSProperties
      }
      className={cn(
        'card-shine-effect pointer-events-none absolute inset-0 size-full rounded-[inherit] will-change-[background-position]',
        className,
      )}
      {...props}
    />
  );
}

[data-variant='default'] {
  --pulse-color: var(--primary);
}
[data-variant='destructive'] {
  --pulse-color: var(--destructive);
}
[data-variant='secondary'] {
  --pulse-color: var(--secondary-foreground);
}
[data-variant='outline'] {
  --pulse-color: var(--ring);
}
[data-variant='ghost'] {
  --pulse-color: var(--ring);
}

.before\:animate-shine-effect::before {
  animation: shine-effect 3s ease-out infinite;
}

.animate-rainbow-effect {
  animation: rainbow-effect 3s linear infinite;
}

.animate-pulsating-effect {
  animation: pulsating-effect 1.5s ease-out infinite;
}

.card-shine-effect {
  animation: card-shine-effect var(--duration) infinite linear;
}

@keyframes shine-effect {
  0% {
    background-position: 200% 0;
  }
  25% {
    background-position: -200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes rainbow-effect {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes pulsating-effect {
  0% {
    box-shadow: 0 0 0 0 var(--pulse-color, currentColor);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes card-shine-effect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

/* ─── Aura Beam ─────────────────────────────────────────────────────────── */

@property --aura-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes aura-spin {
  to {
    --aura-angle: 360deg;
  }
}

.aura-beam {
  --aura-padding: 2px;
  --aura-radius: 0.75rem;
  --aura-duration: 6s;
  --aura-color: var(--primary);
  --aura-color-from: var(--aura-color);
  --aura-color-to: var(--aura-color);

  position: relative;
  display: inline-block;
  padding: var(--aura-padding);
  border-radius: calc(var(--aura-radius) + var(--aura-padding));
  color: var(--aura-color);

  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 220deg,
    currentColor 280deg,
    currentColor 360deg
  );

  animation: aura-spin var(--aura-duration) linear infinite;
}

.aura-beam > * {
  position: relative;
  z-index: 2;
  border-radius: var(--aura-radius);
}

.aura-beam::before,
.aura-beam::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  pointer-events: none;
  z-index: 0;
}

.aura-beam::before {
  filter: blur(6px);
  opacity: 0.65;
}

.aura-beam::after {
  filter: blur(18px);
  opacity: 0.35;
}



/* ─── Beam variant ────────────────────────────────────────────────────────── */

.aura-beam[data-variant='beam'] {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 275deg,
    var(--aura-color-from) 305deg,
    var(--aura-color-to) 325deg,
    transparent 360deg
  );
}

.aura-beam[data-variant='beam']::before {
  filter: blur(4px);
  opacity: 0.85;
}

.aura-beam[data-variant='beam']::after {
  filter: blur(22px);
  opacity: 0.55;
}

/* ─── Shine variant ───────────────────────────────────────────────────────── */

/*
 * Shine uses the same aura-spin rotation as the beam variant — a wide, soft
 * conic arc that rotates continuously. Reusing aura-spin means no separate
 * animation, no back-and-forth, and a perfectly seamless infinite loop.
 */
.aura-beam[data-variant='shine'] {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 120deg,
    var(--aura-color) 210deg,
    transparent 300deg,
    transparent 360deg
  );
}

.aura-beam[data-variant='shine']::before {
  filter: blur(10px);
  opacity: 0.55;
}

.aura-beam[data-variant='shine']::after {
  filter: blur(30px);
  opacity: 0.38;
}
